package pl.d2port;

import android.app.Activity;
import android.content.Context;
import android.graphics.Canvas;
import android.graphics.Color;
import android.graphics.Paint;
import android.os.Bundle;
import android.view.View;
import android.widget.Button;
import android.widget.LinearLayout;
import android.widget.TextView;
import java.io.File;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import pl.d2port.d2.D2Native;
import pl.d2port.data.InstallationManifest;
import pl.d2port.data.InstallationStore;

/** Dev tool: Act I levels as generated by the native D2 core (original DRLG from D2MOO). */
public final class D2MapActivity extends Activity {
    private final ExecutorService worker = Executors.newSingleThreadExecutor();
    private InstallationManifest.Session session;
    private long act;
    private int seed = (int) (System.currentTimeMillis() & 0x7fffffff), level = 1;
    private int[] info, rooms;
    private TextView status;
    private LevelView view;

    @Override public void onCreate(Bundle state) {
        super.onCreate(state);
        LinearLayout root = new LinearLayout(this); root.setOrientation(LinearLayout.VERTICAL);
        LinearLayout bar = new LinearLayout(this);
        addButton(bar, "◀", () -> showLevel(level - 1));
        addButton(bar, "▶", () -> showLevel(level + 1));
        addButton(bar, "Nowe ziarno", () -> { seed = (int) (Math.random() * Integer.MAX_VALUE); build(); });
        addButton(bar, "Kolizje", () -> { view.showCollision = !view.showCollision; view.invalidate(); });
        status = new TextView(this); status.setTextColor(Color.WHITE); status.setPadding(16, 0, 0, 0);
        bar.addView(status);
        root.addView(bar);
        view = new LevelView(this);
        root.addView(view, new LinearLayout.LayoutParams(-1, 0, 1));
        root.setBackgroundColor(Color.BLACK);
        root.setFitsSystemWindows(true); // keep the buttons out from under the status bar
        setContentView(root);
        status.setText("Wczytywanie tabel…");
        worker.execute(() -> {
            try {
                InstallationStore store = new InstallationStore(new File(getFilesDir(), "installation"));
                DataImport.importPending(this, store);
                if (store.current() == null) throw new java.io.IOException("Brak instalacji MPQ");
                session = store.open();
                long t = System.nanoTime();
                boolean ok = D2Native.init(session.data) && D2Native.loadPalette(0);
                long ms = (System.nanoTime() - t) / 1000000;
                runOnUiThread(() -> status.setText(ok ? "Tabele: " + ms + " ms" : "Nie udało się wczytać tabel (logcat D2Native)"));
                if (ok) build();
            } catch (Exception ex) {
                runOnUiThread(() -> status.setText("Błąd: " + ex.getMessage()));
            }
        });
    }

    private void addButton(LinearLayout bar, String text, Runnable action) {
        Button b = new Button(this); b.setText(text); b.setAllCaps(false); b.setOnClickListener(v -> action.run()); bar.addView(b);
    }

    private void build() {
        worker.execute(() -> {
            if (act != 0) D2Native.freeAct(act);
            long t = System.nanoTime();
            act = D2Native.allocAct(0, seed, 0);
            long ms = (System.nanoTime() - t) / 1000000;
            android.util.Log.i("D2Native", "Act I seed " + seed + " in " + ms + " ms");
            loadLevel(level);
        });
    }

    private void showLevel(int l) {
        if (l < 1 || l > 39) return;
        worker.execute(() -> loadLevel(l));
    }

    private void loadLevel(int l) {
        if (act == 0) { runOnUiThread(() -> status.setText("Akt nie został zbudowany")); return; }
        long t = System.nanoTime();
        int[] i = D2Native.levelInfo(act, l);
        if (i == null) return;
        LevelView.Level lv = new LevelView.Level();
        lv.posX = i[2]; lv.posY = i[3]; lv.width = i[4]; lv.height = i[5];
        lv.tiles = D2Native.levelTiles(act, l);
        lv.collision = D2Native.levelCollision(act, l);
        int decoded = 0;
        for (int k = 0; lv.tiles != null && k + 5 < lv.tiles.length; k += 6) {
            int key = lv.tiles[k + 4];
            if (lv.images.containsKey(key)) continue;
            int[] img = D2Native.tileImage(key);
            if (img == null) { lv.images.put(key, null); continue; }
            android.graphics.Bitmap b = android.graphics.Bitmap.createBitmap(img, 4, img[0], img[0], img[1], android.graphics.Bitmap.Config.ARGB_8888);
            lv.images.put(key, b); lv.offsets.put(key, new int[]{img[2], img[3]}); decoded++;
        }
        LevelView.sortDepth(lv);
        long ms = (System.nanoTime() - t) / 1000000;
        final int images = decoded;
        runOnUiThread(() -> {
            level = l; info = i;
            String type = i[0] == 1 ? "labirynt" : i[0] == 2 ? "preset" : "otwarty teren";
            status.setText("Poziom " + l + " (" + type + "), ziarno " + seed + ", " + i[4] + "×" + i[5] + " kafli, pokoje " + i[6] + ", kafli " + (lv.tiles.length / 6) + ", grafik " + images + ", " + ms + " ms");
            view.setLevel(lv);
        });
    }

    @Override protected void onDestroy() {
        super.onDestroy();
        worker.execute(() -> {
            if (act != 0) D2Native.freeAct(act);
            act = 0;
            try { if (session != null) session.close(); } catch (java.io.IOException ignored) {}
        });
        worker.shutdown();
    }

}
